function downloadText(name,text,mime='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function thamudicSaveState(){localStorage.setItem('chimera-thamudic',JSON.stringify(thamudicState));}
function thamudicLoadState(){try{const x=JSON.parse(localStorage.getItem('chimera-thamudic')||'null');if(x)Object.assign(thamudicState,x)}catch{}}
async function thamudicBridge(path,body){const r=await fetch(THAMUDIC_BRIDGE+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());return r.json()}
function thamudicMetrics(){metrics('#thamudicMetrics',[['Glyph Unicode range','U+10A80–U+10A9F'],['Research records',thamudicState.records.length],['Sources',thamudicState.research.length],['Lexicon',thamudicState.lexicon.length],['Boxes',thamudicState.boxes.length],['OCR','automatic']])}
function renderThamudicLexicon(){const l=thamudicState.lexicon.length?thamudicState.lexicon:thamudicDefaultLexicon;$('#lexiconTable').innerHTML=l.map((x,i)=>'<div class="lex-row"><span class="glyph-chip">'+esc(x[0])+'</span><span>'+esc(x[1])+'</span><span>'+esc(x[2])+'</span><span>'+esc(x[3])+'</span></div>').join('')}
function renderThamudicGlyphs(){const el=$('#thamudicGlyphs');el.innerHTML=thamudicState.boxes.map((b,i)=>'<button class="glyph-chip '+(i===thamudicState.selected?'selected':'')+'" data-glyph-index="'+i+'">'+esc(b.glyph||'□')+'</button>').join('');$('[data-glyph-index]').forEach(b=>b.onclick=()=>{thamudicState.selected=Number(b.dataset.glyphIndex);const g=thamudicState.boxes[thamudicState.selected];$('#glyphUnicode').value=g.glyph||'';$('#glyphCodepoint').value=g.codepoint||'';$('#glyphTranslit').value=g.translit||'';$('#glyphNote').value=g.note||'';renderThamudicGlyphs();drawThamudic()})}
function drawThamudic(){const c=$('#thamudicCanvas'),ctx=c?.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);if(!thamudicState.image)return;const im=thamudicState.image;const s=Math.min(c.width/im.width,c.height/im.height),ox=(c.width-im.width*s)/2,oy=(c.height-im.height*s)/2;ctx.drawImage(im,ox,oy,im.width*s,im.height*s);ctx.lineWidth=2;thamudicState.boxes.forEach((b,i)=>{ctx.strokeStyle=i===thamudicState.selected?'#69d5ff':'#b88cff';ctx.strokeRect(ox+b.x*s,oy+b.y*s,b.w*s,b.h*s);ctx.fillStyle='#e8f3ff';ctx.font='14px sans-serif';ctx.fillText(b.glyph||'?',ox+b.x*s+3,oy+b.y*s+16)})}
function connectedBoxes(img,threshold=128){const cv=document.createElement('canvas');cv.width=img.width;cv.height=img.height;const x=cv.getContext('2d');x.drawImage(img,0,0);const d=x.getImageData(0,0,img.width,img.height).data,w=img.width,h=img.height,seen=new Uint8Array(w*h),boxes=[];for(let y=0;y<h;y++)for(let xx=0;xx<w;xx++){const p=y*w+xx;if(seen[p])continue;const lum=.299*d[p*4]+.587*d[p*4+1]+.114*d[p*4+2];if(lum>threshold){seen[p]=1;continue}let q=[[xx,y]],minx=xx,maxx=xx,miny=y,maxy=y,n=0;seen[p]=1;while(q.length){const [cx,cy]=q.pop();n++;minx=Math.min(minx,cx);maxx=Math.max(maxx,cx);miny=Math.min(miny,cy);maxy=Math.max(maxy,cy);for(const [nx,ny] of [[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]]){if(nx<0||ny<0||nx>=w||ny>=h)continue;const z=ny*w+nx;if(seen[z])continue;const l=.299*d[z*4]+.587*d[z*4+1]+.114*d[z*4+2];if(l<=threshold){seen[z]=1;q.push([nx,ny])}}}if(n>=40&&maxx-minx>=3&&maxy-miny>=3&&n< w*h*.25)boxes.push({x:minx,y:miny,w:maxx-minx+1,h:maxy-miny+1,glyph:'□',translit:'?',confidence:0,note:''})}return boxes.sort((a,b)=>a.y-b.y||a.x-b.x).slice(0,1000)}
async function scanThamudic(){if(!thamudicState.image)return alert('Choose an inscription image first.');try{const c=document.createElement('canvas');c.width=thamudicState.image.width;c.height=thamudicState.image.height;c.getContext('2d').drawImage(thamudicState.image,0,0);const r=await thamudicBridge('/thamudic/ocr',{image:c.toDataURL('image/png'),width:c.width,height:c.height,threshold:Number($('#thamudicThreshold').value||128)});thamudicState.boxes=r.boxes||connectedBoxes(thamudicState.image,Number($('#thamudicThreshold').value||128));thamudicState.selected=thamudicState.boxes.length?0:-1;renderThamudicGlyphs();drawThamudic();thamudicMetrics();transliterateThamudic();$('#thamudicConfidence').innerHTML=[r.modelAvailable?'Automatic local vision model':'Automatic segmentation','OCR pipeline connected','Human review required'].map(x=>'<span>'+x+'</span>').join('')}catch(e){thamudicState.boxes=connectedBoxes(thamudicState.image,Number($('#thamudicThreshold').value||128));thamudicState.selected=thamudicState.boxes.length?0:-1;renderThamudicGlyphs();drawThamudic();thamudicMetrics();transliterateThamudic();$('#thamudicConfidence').innerHTML=['Browser segmentation fallback','Local OCR bridge offline','Human review required'].map(x=>'<span>'+x+'</span>').join('')}}
function transliterateThamudic(){const text=thamudicState.boxes.map(b=>b.glyph&&b.glyph!=='□'?b.glyph:(b.translit&&b.translit!=='?'?b.translit:'?')).join('');const local=thamudicState.boxes.map(b=>b.translit&&b.translit!=='?'?b.translit:'?').join('');$('#thamudicTranslit').textContent=local||'—';return text}
async function runThamudicNlp(action='translate'){const text=transliterateThamudic();if(!text||text.replace(/\?/g,'').trim()===''){const el=$('#thamudicNlpStatus');if(el)el.innerHTML='<span>No reviewed glyph sequence yet</span>';return}const target=$('#thamudicTarget')?.value||'english',mode=$('#thamudicNlpMode')?.value||'research';try{const r=await thamudicBridge(action==='analyze'?'/nlp/analyze':'/nlp/translate',{text,target,mode});$('#thamudicTranslit').textContent=r.transliteration||'—';$('#thamudicTranslation').value=r.translation||'';$('#thamudicNlpStatus').innerHTML=[['Backend: '+(r.backend||'unknown')],['Status: '+(r.status||'ready')],['Confidence: '+Number(r.confidence||0).toFixed(2)],r.uncertain?.length?['Uncertain glyphs: '+r.uncertain.length]:['Uncertainty tracked']].map(x=>'<span>'+esc(x[0])+'</span>').join('');if(action==='analyze')$('#thamudicModelLog').textContent=JSON.stringify(r,null,2);return r}catch(e){$('#thamudicNlpStatus').innerHTML='<span>NLP backend error: '+esc(e.message)+'</span>';throw e}}

function assignThamudic(){if(thamudicState.selected<0)return;const b=thamudicState.boxes[thamudicState.selected];b.glyph=$('#glyphUnicode').value||'□';b.codepoint=$('#glyphCodepoint').value||'';b.translit=$('#glyphTranslit').value||'?';b.note=$('#glyphNote').value||'';b.confidence=.95;$('#thamudicTranslit').textContent=transliterateThamudic();renderThamudicGlyphs();drawThamudic();thamudicSaveState()}
function thamudicRecord(){const rec={id:crypto.randomUUID(),createdAt:new Date().toISOString(),order:$('#thamudicOrder').value,imageName:$('#thamudicFile').files[0]?.name||'',glyphs:thamudicState.boxes,transliteration:transliterateThamudic(),translation:$('#thamudicTranslation').value||'',sourceUrls:thamudicState.research.map(x=>x.url).filter(Boolean)};thamudicState.records.push(rec);thamudicSaveState();thamudicMetrics();$('#thamudicExportPreview').textContent=JSON.stringify(rec,null,2);log('Saved Thamudic research record '+rec.id)}
function renderResearch(){const el=$('#thamudicResults');el.innerHTML=thamudicState.research.map((x,i)=>'<article class="research-card">'+(x.thumbnail?'<img src="'+esc(x.thumbnail)+'" loading="lazy">':'')+'<h3>'+esc(x.title||x.name||'Research source')+'</h3><p>'+esc(x.description||x.snippet||'')+'</p><p class="muted">'+esc(x.license||'license unknown')+' · '+esc(x.source||'')+'</p><div class="actions"><button data-research="'+i+'">Use source</button></div></article>').join('');$('[data-research]').forEach(b=>b.onclick=()=>{const x=thamudicState.research[Number(b.dataset.research)];$('#thamudicTranslation').value=x.translation||'';log('Research source selected: '+(x.title||x.name||''))})}
async function searchThamudic(){try{const r=await thamudicBridge('/thamudic/search',{query:$('#thamudicQuery').value,limit:Number($('#thamudicLimit').value||20)});thamudicState.research=r.results||[];renderResearch();thamudicMetrics();}catch(e){alert('Local research bridge unavailable: '+e.message)}}
async function trainThamudic(){try{const r=await thamudicBridge('/thamudic/train',{model:$('#thamudicModel').value,epochs:Number($('#thamudicEpochs').value),batch:Number($('#thamudicBatch').value),lr:Number($('#thamudicLR').value)});$('#thamudicModelLog').textContent=JSON.stringify(r,null,2);thamudicState.model=r;thamudicSaveState()}catch(e){$('#thamudicModelLog').textContent='Local model bridge unavailable: '+e.message}}
async function predictThamudic(){try{const r=await thamudicBridge('/thamudic/predict',{boxes:thamudicState.boxes,order:$('#thamudicOrder').value});thamudicState.boxes=(r.glyphs||thamudicState.boxes);$('#thamudicTranslit').textContent=r.transliteration||transliterateThamudic();$('#thamudicTranslation').value=r.translation||$('#thamudicTranslation').value;renderThamudicGlyphs();drawThamudic();}catch(e){log('Prediction requires the local Thamudic NLP bridge: '+e.message)}}
function exportThamudic(kind){const r=thamudicState.records.at(-1)||{glyphs:thamudicState.boxes,transliteration:transliterateThamudic(),translation:$('#thamudicTranslation').value||'',sourceUrls:thamudicState.research.map(x=>x.url).filter(Boolean)};if(kind==='csv'){downloadText('thamudic-research.csv','glyph,codepoint,transliteration,confidence,note\n'+(r.glyphs||[]).map(x=>[x.glyph,x.codepoint,x.translit,x.confidence,x.note].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')}else if(kind==='tei'){downloadText('thamudic-research.xml','<?xml version="1.0" encoding="UTF-8"?><TEI><text><body><ab>'+esc(r.glyphs?.map(x=>x.glyph||'□').join('')||'')+'</ab><interp>'+esc(r.translation||'')+'</interp></body></text></TEI>','application/xml')}else{downloadText('thamudic-research.jsonld',JSON.stringify({'@context':{'glyph':'https://example.org/thamudic/glyph','transliteration':'https://example.org/thamudic/transliteration'},'@type':'EpigraphicResearchRecord',...r},null,2))}}
function setupThamudic(){thamudicLoadState();if(!thamudicState.lexicon.length)thamudicState.lexicon=thamudicDefaultLexicon;$('.thamudic-tabs .tab').forEach(b=>b.onclick=()=>{$('.thamudic-tabs .tab').forEach(x=>x.classList.remove('active'));$('.ttab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('[data-ttab-panel="'+b.dataset.ttab+'"]').classList.add('active')});$('#thamudicFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const im=new Image();im.onload=()=>{thamudicState.image=im;drawThamudic()};im.src=URL.createObjectURL(f)};$('#thamudicScan').onclick=scanThamudic;$('#thamudicClear').onclick=()=>{thamudicState.boxes=[];thamudicState.selected=-1;drawThamudic();renderThamudicGlyphs()};$('#assignGlyph').onclick=assignThamudic;$('#nextGlyph').onclick=()=>{if(thamudicState.boxes.length)thamudicState.selected=(thamudicState.selected+1)%thamudicState.boxes.length;renderThamudicGlyphs();drawThamudic()};$('#thamudicSave').onclick=thamudicRecord;$('#thamudicSearch').onclick=searchThamudic;$('#thamudicCrawl').onclick=async()=>{try{const r=await thamudicBridge('/thamudic/crawl',{sources:thamudicState.research});thamudicState.research=r.results||thamudicState.research;renderResearch()}catch(e){alert(e.message)}};$('#thamudicDownload').onclick=()=>log('Selected research images are downloaded by the local bridge into its provenance dataset.');$('#trainThamudic').onclick=trainThamudic;$('#importModel').onclick=()=>{const raw=prompt('Paste model metadata JSON');if(raw===null)return;try{const model=JSON.parse(raw);thamudicState.model=model;thamudicSaveState();$('#thamudicModelLog').textContent=JSON.stringify({status:'imported',model},null,2);log('Imported Thamudic model metadata')}catch(e){$('#thamudicModelLog').textContent='Invalid model metadata JSON: '+e.message}};$('#thamudicPredict').onclick=predictThamudic;$('#thamudicTranslate').onclick=()=>runThamudicNlp('translate');$('#thamudicAnalyze').onclick=()=>runThamudicNlp('analyze');$('#evaluateThamudic').onclick=async()=>{try{$('#thamudicModelLog').textContent=JSON.stringify(await thamudicBridge('/thamudic/evaluate',{}),null,2)}catch(e){$('#thamudicModelLog').textContent=e.message}};$('#assignGlyph').onclick=assignThamudic;$('#addLexicon').onclick=()=>$('#lexAdd').click();$('#lexAdd').onclick=()=>{thamudicState.lexicon.push([$('#lexGlyph').value,$('#lexTranslit').value,$('#lexMeaning').value,$('#lexSource').value]);renderThamudicLexicon();thamudicSaveState()};$('#lexExport').onclick=()=>downloadText('thamudic-lexicon.json',JSON.stringify(thamudicState.lexicon,null,2));$('#buildDataset').onclick=()=>{$('#datasetSummary').innerHTML='<div class="chips"><span>Reviewed records: '+thamudicState.records.length+'</span><span>Glyph samples: '+thamudicState.records.reduce((n,r)=>n+(r.glyphs?.length||0),0)+'</span><span>Provenance attached</span></div>';thamudicSaveState()};$('#exportDataset').onclick=()=>downloadText('thamudic-dataset-manifest.json',JSON.stringify({version:1,createdAt:new Date().toISOString(),records:thamudicState.records,sources:thamudicState.research},null,2));$('#exportThamudicCSV').onclick=()=>exportThamudic('csv');$('#exportThamudicJSON').onclick=()=>exportThamudic('json');$('#exportThamudicTEI').onclick=()=>exportThamudic('tei');renderThamudicLexicon();renderThamudicGlyphs();thamudicMetrics();thamudicBridge('/health').then(()=>$('#thamudicBridgeBadge').textContent='Local NLP bridge: online').catch(()=>$('#thamudicBridgeBadge').textContent='Local NLP bridge: offline')}

const defaultControls = {up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight',fire1:'KeyZ',fire2:'KeyX',start:'Enter',select:'ShiftLeft',menu:'Tab',pause:'Escape',virtualKeyboard:'F12',save:'F5',load:'F7'};
let db,selectedMachine=null,listenAction=null, mameCore={js:null,wasm:null,loaded:false};
async function mameStoreFiles(){
 const files=[...($('#mameRomFile')?.files||[])]; if(!files.length){log('No ROM/software files selected.');return;}
 for(const f of files){await put('mame-roms',{id:'rom:'+f.name,size:f.size,name:f.name,type:f.type||'application/octet-stream',blob:f,lastModified:f.lastModified});}
 await renderMameRomInventory(); log('Stored '+files.length+' user-supplied ROM/software file(s) in IndexedDB.');
}
async function renderMameRomInventory(){
 const el=$('#mameRomInventory'); if(!el)return;
 try{const a=await all('mame-roms');el.innerHTML=a.length?a.map(x=>'<span>'+esc(x.name)+' · '+Math.round(x.size/1024)+' KB</span>').join(''):'<span>No ROMs stored</span>';
 const st=$('#mameRuntimeStatus'); if(st)st.textContent='Core: '+(mameCore.loaded?'loaded locally':'not loaded')+' · ROMs: user-supplied ('+a.length+') · storage: IndexedDB';
 }catch(e){if(el)el.innerHTML='<span>ROM storage unavailable</span>'}
}
async function mameLoadCore(){
 const jsFile=$('#mameCoreJs')?.files?.[0], wasmFile=$('#mameCoreWasm')?.files?.[0];
 if(!jsFile&&!wasmFile){alert('Select the MAME WebAssembly JavaScript and/or WASM runtime first.');return;}
 if(wasmFile)await put('mame-core',{id:'wasm',name:wasmFile.name,size:wasmFile.size,blob:wasmFile});
 if(jsFile)await put('mame-core',{id:'js',name:jsFile.name,size:jsFile.size,blob:jsFile});
 mameCore={js:jsFile?.name||null,wasm:wasmFile?.name||null,loaded:true};
 $('#mameCoreBadge').textContent='Browser core: staged';
 $('#mameCoreBadge').title='Core assets stored locally. The MAME build must expose its Emscripten runtime/Module interface before emulation can start.';
 await renderMameRomInventory(); log('MAME WebAssembly core staged in IndexedDB.');}
async function mameResetCore(){mameCore={js:null,wasm:null,loaded:false};try{for(const x of await all('mame-core'))await new Promise((res,rej)=>{const t=db.transaction('mame-core','readwrite');t.objectStore('mame-core').delete(x.id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}catch{}$('#mameCoreBadge').textContent='Browser core: not loaded';await renderMameRomInventory();}

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function log(s){const el=$('#dbLog');if(el){el.textContent+=(el.textContent?'\n':'')+s;el.scrollTop=el.scrollHeight}}
function metrics(el,rows){$(el).innerHTML=rows.map(x=>'<div class="metric"><span>'+esc(x[0])+'</span><strong>'+esc(x[1])+'</strong></div>').join('')}
function rows(el,arr){$(el).innerHTML=arr.map(x=>'<div class="list-row"><strong>'+esc(x[0])+'</strong><span class="muted">'+esc(x[1])+'</span></div>').join('')}
function openDB(){
 return new Promise((resolve,reject)=>{const r=indexedDB.open('chimera-ii-control',3);r.onupgradeneeded=()=>{const d=r.result;['settings','machines','games','controls','saves','mame-roms','mame-core'].forEach(n=>{if(!d.objectStoreNames.contains(n))d.createObjectStore(n,{keyPath:'id'})})};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)})
}
function put(store,obj){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(obj);t.oncomplete=()=>res();t.onerror=()=>rej(t.error)})}
function all(store){return new Promise((res,rej)=>{const t=db.transaction(store);const r=t.objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function initDBData(){
 return Promise.all([all('machines'),all('games')]).then(([m,g])=>Promise.all([
  m.length?null:Promise.all(systems.map(s=>put('machines',{id:s[0],name:s[1],family:s[2],manufacturer:s[3],favorite:false}))),
  g.length?null:Promise.all(gameCatalog.map(x=>put('games',{id:x[0],title:x[1],genre:x[2],provider:x[3],layer:x[4],favorite:false})))
 ]))
}
async function bridge(path,body){
 try{const r=await fetch(BRIDGE+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(r.status);return await r.json()}catch(e){throw e}
}
async function checkBridge(){
 try{const r=await bridge('/health');$('#bridgeDot').className='dot ok';$('#bridgeText').textContent='Local bridge: '+(r.version||'online');if($('#mameRuntimeStatus'))$('#mameRuntimeStatus').textContent='Core: native MAME bridge available · ROMs: user-supplied · storage: IndexedDB';if($('#mameCoreBadge'))$('#mameCoreBadge').textContent='Native core: available';$('#amigaStatus').textContent='Bridge online. Local cores are available to launch outside Pages.';return true}
 catch(e){$('#bridgeDot').className='dot bad';$('#bridgeText').textContent='Local bridge: offline';if($('#mameRuntimeStatus'))$('#mameRuntimeStatus').textContent='Core: browser core optional · native bridge offline · ROMs: user-supplied · storage: IndexedDB';if($('#mameCoreBadge'))$('#mameCoreBadge').textContent=mameCore.loaded?'Browser core: staged':'Browser core: not loaded';$('#amigaStatus').textContent='Bridge offline. Install/start tools/amiga-local-core/bridge.py locally to launch the Amiga core.';return false}
}
function show(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));$$('.hub-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));location.hash=view}
function setupNav(){$('.hub-nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));const h=location.hash.slice(1);if(h&&($('#view-'+h)||h==='thamudic'))show(h);window.addEventListener('hashchange',()=>{const x=location.hash.slice(1);if(x&&($('#view-'+x)||x==='thamudic'))show(x)})}
function overview(){metrics('#overviewMetrics',[['Systems',systems.length],['Games',gameCatalog.length],['BizX modules',bizxModules.length],['BizXtreme events',bx.events.length],['Input actions',Object.keys(controls).length],['DB schema','v3']])}
function renderMame(){
 const q=($('#mameSearch').value||'').toLowerCase(), f=$('#mameFilter').value;
 const list=systems.filter(s=>(f==='all'||(f==='favorite'&&false)||s[2].toLowerCase()===f||s[2].toLowerCase().includes(f))&&(s.join(' ').toLowerCase().includes(q)));
 $('#mameCount').textContent=list.length+' machines';
 $('#machineList').innerHTML=list.map(s=>'<div class="machine '+(selectedMachine?.[0]===s[0]?'selected':'')+'" data-id="'+esc(s[0])+'"><strong>'+esc(s[1])+'</strong><small>'+esc(s[2])+' · '+esc(s[3])+' · '+esc(s[0])+'</small></div>').join('');
 $$('.machine').forEach(x=>x.onclick=()=>{selectedMachine=systems.find(s=>s[0]===x.dataset.id);renderMame();renderMachineDetail()})
}
function renderMachineDetail(){if(!selectedMachine){$('#machineDetail').innerHTML='<div class="empty">Select a machine.</div>';return}const s=selectedMachine;$('#machineDetail').innerHTML='<div class="section-head"><div><span class="eyebrow">'+esc(s[2])+'</span><h3>'+esc(s[1])+'</h3><p class="muted">MAME driver: '+esc(s[0])+' · '+esc(s[3])+'</p></div><button id="favMachine">☆ Favorite</button></div><div class="chips"><span>ROM verify</span><span>Software lists</span><span>Slots</span><span>Input remapping</span><span>Save states</span><span>Debugger</span><span>Snapshots</span><span>Recording</span></div>';$('#favMachine').onclick=()=>{put('machines',{id:s[0],name:s[1],family:s[2],manufacturer:s[3],favorite:true});log('Favorite: '+s[1])}}
function mameCommand(extra=[]){if(!selectedMachine)return 'mame';const path=$('#mameRomPath').value.trim()||'roms';let c=['mame',selectedMachine[0],'-rompath',path,'-video',$('#mameVideo').value];if($('#mameWindow').value==='fullscreen')c.push('-maximize');const sp=Number($('#mameSpeed').value||1);if(sp!==1)c.push('-speed',sp);if($('#autosave').value==='on')c.push('-autosave');if($('#rewind').value==='on')c.push('-rewind','-rewind_capacity',$('#rewindCap').value);if($('#debugger').value)c.push(...extra);return c.join(' ')}
function updateMameCommand(){if($('#mameCommand'))$('#mameCommand').textContent=mameCommand()}
function setupMame(){
 $('#mameLoadCore').onclick=mameLoadCore;$('#mameRunCore').onclick=async()=>{try{const a=await all('mame-core'),js=a.find(x=>x.id==='js'),wasm=a.find(x=>x.id==='wasm'),roms=await all('mame-roms');if(!window.ChimeraMameWeb)throw Error('MAME browser runtime glue is unavailable.');await window.ChimeraMameWeb.start({js,wasm,roms,machine:selectedMachine?.[0]||''});log('MAME browser core start requested.')}catch(e){alert('MAME browser core: '+e.message);log('MAME browser core error: '+e.message)}};$('#mameStopCore').onclick=()=>{window.ChimeraMameWeb?.stop();if($('#mameRuntimeStatus'))$('#mameRuntimeStatus').textContent='Browser MAME runtime stopped · ROMs remain in IndexedDB'};$('#mameStoreRoms').onclick=mameStoreFiles;$('#mameCoreReset').onclick=mameResetCore;$('#mameClearRoms').onclick=async()=>{for(const x of await all('mame-roms'))await new Promise((res,rej)=>{const t=db.transaction('mame-roms','readwrite');t.objectStore('mame-roms').delete(x.id);t.oncomplete=res;t.onerror=()=>rej(t.error)});await renderMameRomInventory();log('Stored MAME ROM/software cache cleared.');};
 renderMameRomInventory();
 $('#mameSearch').oninput=renderMame;$('#mameFilter').onchange=renderMame;
 $$('#view-mame input,#view-mame select').forEach(x=>x.addEventListener('change',updateMameCommand));
 $$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));$$('.mtab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('[data-mtab-panel="'+b.dataset.mtab+'"]').classList.add('active')});
 $('#mameLaunch').onclick=async()=>{const ok=await checkBridge();if(!ok){alert('Local bridge is offline.');return}try{await bridge('/launch/mame',{command:mameCommand()});log('MAME launch requested: '+mameCommand())}catch(e){alert('Bridge rejected MAME launch: '+e.message)}};
 $('#mameCopy').onclick=()=>navigator.clipboard?.writeText(mameCommand()).then(()=>log('MAME command copied.'));
 $('#mameValidate').onclick=async()=>{try{const r=await bridge('/mame/validate',{machine:selectedMachine?.[0],rompath:$('#mameRomPath').value||'roms'});log(JSON.stringify(r))}catch(e){log('Validation requires local bridge.')}};
 $('#mameImport').onclick=()=>{const i=document.createElement('input');i.type='file';i.accept='.xml';i.onchange=async()=>{const f=i.files[0];if(!f)return;const t=await f.text();const doc=new DOMParser().parseFromString(t,'application/xml');const nodes=[...doc.querySelectorAll('machine')];for(const n of nodes.slice(0,5000)){const id=n.getAttribute('name');if(!id)continue;await put('machines',{id,name:n.getAttribute('description')||id,family:'MAME',manufacturer:n.querySelector('manufacturer')?.textContent||'',favorite:false})}log('Imported '+nodes.length+' MAME machines from listxml.');const ms=await all('machines');$('#mameCount').textContent=ms.length+' database entries';renderMame()};i.click()};
 $('#mameInputPanel').innerHTML='<div class="control-grid">'+Object.entries(controls).map(([k,v])=>'<div><strong>'+esc(k)+'</strong><br><span class="muted">'+esc(v)+'</span></div>').join('')+'</div>';
 async function mameAction(action,payload={}){try{await bridge('/mame/'+action,{machine:selectedMachine?.[0]||'',...payload});log('MAME '+action+' request accepted.')}catch(e){log('MAME '+action+' unavailable: '+e.message);alert('MAME '+action+': local bridge unavailable.')}}
 $('#stateSave').onclick=()=>mameAction('state/save',{slot:Number($('#stateSlot').value||1)});$('#stateLoad').onclick=()=>mameAction('state/load',{slot:Number($('#stateSlot').value||1)});$('#record').onclick=()=>mameAction('record',{enabled:true});$('#snapshot').onclick=()=>mameAction('snapshot',{path:'chimera-snapshot.png'});$('#debugLaunch').onclick=()=>mameAction('debug',{debugger:$('#debugger').value,host:$('#debugHost').value,port:Number($('#debugPort').value||23946),command:mameCommand(['-debug','-debugger',$('#debugger').value])});$('#mediaMount').onclick=()=>mameAction('media/mount',{slot:$('#mediaSlot').value,path:$('#mediaPath').value});$('#mediaEject').onclick=()=>mameAction('media/eject',{slot:$('#mediaSlot').value});
 renderMame();renderMachineDetail();updateMameCommand()
}
let gameManifest=null;
const gameLobby={ws:null,peers:new Map(),id:(crypto.randomUUID?crypto.randomUUID():String(Date.now()))};
async function loadGameManifest(){try{const r=await fetch('game-center-manifest.json',{cache:'no-store'});if(!r.ok)throw Error('manifest '+r.status);gameManifest=await r.json();gameCatalog=gameManifest.games.map(x=>[x[0],x[1],x[2],x[3],x[5],x[4],x[6],x[7]]);return true}catch(e){log('Game manifest fallback: '+e.message);return false}}
function gameLaunchHint(x){return x[4]==='native-elf'?'Local build/runtime required':'Browser runtime'}
function renderGames(){
 const q=($('#gameSearch').value||'').toLowerCase(), fam=$('#gameFamily').value;
 const rows=gameCatalog.filter(x=>(fam==='all'||x[2]===fam)&&(x.join(' ').toLowerCase().includes(q)));
 $('#gamesGrid').innerHTML=rows.map(x=>'<article class="game-card"><h3>'+esc(x[1])+'</h3><p>'+esc(x[2])+' · '+esc(x[3])+'</p><div class="chips"><span>'+esc(x[4])+'</span><span>'+(x[5]?'🌐 Multiplayer':'Solo')+'</span><span>'+esc(gameLaunchHint(x))+'</span></div><div class="actions"><button data-launch="'+esc(x[0])+'">Run</button><button data-game="'+esc(x[0])+'">Favorite</button><button data-source="'+esc(x[0])+'">Source</button>'+(x[5]?'<button data-lobby="'+esc(x[0])+'">Lobby</button>':'')+'</div><small class="muted">'+esc(x[7]||'')+'</small><div class="chips">'+((gameManifest?.featuredAssetProfiles?.[x[2]]||[]).map(a=>'<span>3D/art: '+esc(a)+'</span>').join(''))+'</div></article>').join('');
 $('#gamesGrid [data-game]').forEach(b=>b.onclick=()=>{const x=gameCatalog.find(g=>g[0]===b.dataset.game);put('games',{id:x[0],title:x[1],genre:x[2],provider:x[3],layer:x[4],multiplayer:!!x[5],source:x[6],site:x[7],favorite:true});b.textContent='Favorited';log('Game favorite: '+x[1])});
 $('#gamesGrid [data-source]').forEach(b=>b.onclick=()=>{const x=gameCatalog.find(g=>g[0]===b.dataset.source);window.open(x[6]||x[7],'_blank','noopener')});
 $('#gamesGrid [data-launch]').forEach(b=>b.onclick=async()=>{const x=gameCatalog.find(g=>g[0]===b.dataset.launch);b.disabled=true;const old=b.textContent;b.textContent='Running…';try{if(x[4]==='browser'){const url=x[6]||x[7];if(url)window.open(url,'_blank','noopener');else throw Error('No browser runtime URL is registered.')}else{const r=await fetch(GAME_BRIDGE+'/games/launch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:x[0]})});const j=await r.json();if(!r.ok)throw Error(j.error||'launch failed');log('Launched '+x[1])}}catch(e){alert(x[1]+': '+e.message+'\\nLocal native runtime may require tools/game-center/build-open-games.sh')}finally{setTimeout(()=>{b.disabled=false;b.textContent=old},1200)}});
 $('#gamesGrid [data-lobby]').forEach(b=>b.onclick=()=>joinGameLobby(b.dataset.lobby));
 $('#gameStats').innerHTML='<span>'+rows.length+' results</span><span>'+new Set(gameCatalog.map(x=>x[2])).size+' genres</span><span>'+gameCatalog.filter(x=>x[5]).length+' multiplayer</span><span>License-verified metadata</span>';
 if(gameManifest)$('#gameAssets').innerHTML=gameManifest.assetSources.map(a=>'<a href="'+esc(a[3])+'" target="_blank" rel="noopener"><span>'+esc(a[1])+' · '+esc(a[2])+'</span></a>').join('');
}
function gameLobbyRender(){const a=[...gameLobby.peers.values()];$('#gamePeers').innerHTML=a.length?a.map(p=>'<div class="peer"><span class="avatar">'+esc(p.avatar||'✦')+'</span><div class="grow"><b>'+esc(p.nick||'Player')+'</b><small class="muted"> '+esc(p.game||'lobby')+'</small></div><button data-gp="'+esc(p.id)+'">Invite</button></div>').join(''):'<div class="empty">No lobby peers yet.</div>'}
function gameLobbyConnect(host=false){const url=$('#gameSignal').value.trim();if(!/^wss?:\/\//.test(url)){alert('Enter a ws:// or wss:// signaling endpoint.');return}if(gameLobby.ws)gameLobby.ws.close();gameLobby.ws=new WebSocket(url);gameLobby.ws.onopen=()=>{const msg={type:'join',room:$('#gameRoom').value.trim()||'chimera-game-center',peer:{id:gameLobby.id,nick:$('#gameNick').value.trim()||'Chimera Player',avatar:'✦',game:'game-center',host}};gameLobby.ws.send(JSON.stringify(msg));$('#gameLobbyStatus').innerHTML='<span>Connected to signaling</span><span>Room: '+esc(msg.room)+'</span>';log('Game lobby connected: '+msg.room)};gameLobby.ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.type==='presence'&&m.id!==gameLobby.id)gameLobby.peers.set(m.id,m);if(m.type==='peers')(m.peers||[]).forEach(p=>p.id!==gameLobby.id&&gameLobby.peers.set(p.id,p));gameLobbyRender()}catch{}};gameLobby.ws.onclose=()=>$('#gameLobbyStatus').innerHTML='<span>Lobby disconnected</span>'}
function joinGameLobby(gameId){$('#gameRoom').value='chimera-'+gameId;document.getElementById('gameLobbyConnect')?.scrollIntoView({behavior:'smooth',block:'center'});$('#gameLobbyStatus').innerHTML='<span>Room prepared for '+esc(gameId)+'</span><span>Connect signaling to join</span>'}
function setupGames(){const fam=[...new Set(gameCatalog.map(x=>x[2]))].sort();$('#gameFamily').innerHTML='<option value="all">All genres</option>'+fam.map(x=>'<option>'+esc(x)+'</option>').join('');$('#gameSearch').oninput=renderGames;$('#gameFamily').onchange=renderGames;$('#gameLobbyConnect').onclick=()=>gameLobbyConnect(false);$('#gameLobbyHost').onclick=()=>gameLobbyConnect(true);$('#gameLobbyRefresh').onclick=gameLobbyRender;loadGameManifest().finally(renderGames)}
function renderBizx(){metrics('#bizxKpis',[['Systems contract','deterministic'],['Languages','Node · Java · Python'],['Game systems','20+'],['Wallet boundary','provider'],['Network','authoritative'],['Asset policy','verified']]);$('#bizxModules').innerHTML=bizxModules.map(x=>'<article class="panel"><h3>'+esc(x[0])+'</h3><p class="muted">'+esc(x[1])+'</p></article>').join('')}
function renderBizXtreme(){metrics('#bxKpis',bx.kpis);rows('#chapters',bx.chapters);rows('#events',bx.events);rows('#inventory',bx.inventory);rows('#market',bx.market)}
function setupBx(){renderBizXtreme();$('#starterPack').onclick=()=>{localStorage.setItem('chimera-starter-pack','claimed');log('Frontier Starter Pack marked claimed locally.');alert('Starter Pack claimed locally.');};$('#newSave').onclick=()=>{const save={version:1,tick:0,score:0,xp:0,expedition:0,createdAt:new Date().toISOString()};put('saves',{id:'bizxtreme-current',...save});log('New BizXtreme local save created.');}}
function renderControls(){const el=$('#controlEditor');el.innerHTML=Object.entries(controls).map(([k,v])=>'<div class="bind"><span>'+esc(k)+'</span><button data-bind="'+esc(k)+'">'+esc(v)+'</button></div>').join('');$$('[data-bind]').forEach(b=>b.onclick=()=>{listenAction=b.dataset.bind;b.classList.add('listening');b.textContent='Press key…'})}
function setupControls(){renderControls();window.addEventListener('keydown',async e=>{if(!listenAction)return;e.preventDefault();controls[listenAction]=e.code;await put('controls',{id:'default',bindings:controls});listenAction=null;renderControls();$('#mameInputPanel').innerHTML='<div class="control-grid">'+Object.entries(controls).map(([k,v])=>'<div><strong>'+esc(k)+'</strong><br><span class="muted">'+esc(v)+'</span></div>').join('')+'</div>';log('Bound '+e.code)});$('#resetControls').onclick=()=>{Object.assign(controls,defaultControls);put('controls',{id:'default',bindings:controls});renderControls();log('Controls reset.')}}
async function databaseView(){const [m,g,s,c]=await Promise.all([all('machines'),all('games'),all('saves'),all('controls')]);$('#dbSummary').innerHTML='<div class="chips"><span>Machines: '+m.length+'</span><span>Games: '+g.length+'</span><span>Saves: '+s.length+'</span><span>Profiles: '+c.length+'</span><span>IndexedDB v3</span></div>'}
async function exportDB(){const out={version:3,exportedAt:new Date().toISOString(),machines:await all('machines'),games:await all('games'),saves:await all('saves'),controls:await all('controls')};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='chimera-ii-database.json';a.click();log('Database exported.')}
function setupDB(){$('#exportDb').onclick=exportDB;$('#importDb').onclick=()=>$('#dbFile').click();$('#dbFile').onchange=async()=>{const f=$('#dbFile').files[0];if(!f)return;const o=JSON.parse(await f.text());for(const n of ['machines','games','saves','controls'])for(const x of o[n]||[])await put(n,x);log('Database imported.');databaseView()};databaseView()}
function setupAmiga(){const c=[['Joystick','D-pad / left stick'],['Mouse','Right stick'],['Fire 1','Z / A'],['Fire 2','X / B'],['Virtual keyboard','F12 / Select'],['Status bar','F11 / Select long']];$('#amigaControls').innerHTML=c.map(x=>'<div><strong>'+esc(x[0])+'</strong><br><span class="muted">'+esc(x[1])+'</span></div>').join('');$('#amigaDetect').onclick=checkBridge;$('#amigaLaunch').onclick=async()=>{if(!await checkBridge())return;try{await bridge('/launch/amiga',{model:$('#amigaModel').value,video:$('#amigaVideo').value,lineMode:$('#amigaLine').value,content:$('#amigaContent').value});log('Amiga local launch requested.')}catch(e){alert('Local Amiga launch failed: '+e.message)}}}
